export function GhostButton({ children }: { children: React.ReactNode }) {
  return (
    <button className="group relative inline-flex items-center justify-center overflow-hidden rounded-lg border border-zinc-300 px-5 py-2.5 text-sm font-medium text-zinc-700 transition-colors duration-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-zinc-400 active:scale-[0.97] dark:border-zinc-600 dark:text-zinc-200">
      <span
        aria-hidden
        className="absolute inset-0 origin-left scale-x-0 bg-zinc-900 transition-transform duration-300 ease-out group-hover:scale-x-100 motion-reduce:transition-none dark:bg-white"
      />
      <span className="relative transition-colors duration-300 group-hover:text-white dark:group-hover:text-zinc-900">
        {children}
      </span>
    </button>
  );
}
